content:
:root {
  --primary-color: #2563eb;
  --primary-hover: #1d4ed8;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --table-header-bg: #f8fafc;
  --radius: 12px;
  --shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
}

@media (prefers-color-scheme: dark) {
  :root {
    --primary-color: #3b82f6;
    --primary-hover: #60a5fa;
    --bg-color: #0f172a;
    --card-bg: #1e293b;
    --text-main: #f8fafc;
    --text-muted: #94a3b8;
    --border-color: #334155;
    --table-header-bg: #0f172a;
    --shadow: 0 4px 6px -1px rgb(0 0 0 / 0.5), 0 2px 4px -2px rgb(0 0 0 / 0.3);
  }
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
}

.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 2rem 1rem;
}

.header {
  margin-bottom: 2rem;
  text-align: center;
}

.header h1 {
  font-size: 2rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 0.5rem;
}

.header p {
  color: var(--text-muted);
  font-size: 1rem;
}

.simulator-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
}

@media (min-width: 768px) {
  .simulator-grid {
    grid-template-columns: 380px 1fr;
  }
}

.input-panel {
  background-color: var(--card-bg);
  padding: 1.5rem;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  height: fit-content;
}

.result-panel {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.input-group {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.label-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-weight: 600;
  font-size: 0.95rem;
}

.input {
  width: 100%;
  min-height: 44px; /* モバイルのタッチターゲット確保 */
  padding: 0.75rem 1rem;
  font-size: 1rem;
  border: 1px solid var(--border-color);
  background-color: var(--card-bg);
  color: var(--text-main);
  border-radius: 8px;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.input:focus {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.25);
}

.range-input {
  width: 100%;
  min-height: 44px; /* モバイルのタッチターゲット確保 */
  accent-color: var(--primary-color);
  cursor: pointer;
}

.summary-cards {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1rem;
}

@media (min-width: 640px) {
  .summary-cards {
    grid-template-columns: repeat(3, 1fr);
  }
}

.summary-card {
  background-color: var(--card-bg);
  padding: 1.25rem;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.summary-card h3 {
  font-size: 0.875rem;
  color: var(--text-muted);
  font-weight: 500;
}

.summary-card .value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary-color);
}

.chart-card {
  background-color: var(--card-bg);
  padding: 1.5rem;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}

.chart-card h2 {
  font-size: 1.25rem;
  margin-bottom: 1rem;
  font-weight: 600;
}

.table-card {
  background-color: var(--card-bg);
  padding: 1.5rem;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  overflow-x: auto;
}

.table-card h2 {
  font-size: 1.25rem;
  margin-bottom: 1rem;
  font-weight: 600;
}

.table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.875rem;
}

.table th,
.table td {
  padding: 0.75rem 1rem;
  border-bottom: 1px solid var(--border-color);
}

.table th {
  font-weight: 600;
  color: var(--text-muted);
  background-color: var(--table-header-bg);
}

.table tr:hover {
  background-color: var(--border-color);
}

/**
 * 住宅ローンシミュレーションの入力パラメータ
 */
export interface LoanParams {
  /** 借入金額（円）※許容範囲: 1,000,000 ~ 100,000,000 */
  amount: number;
  /** 金利（年利 %）※許容範囲: 0 ~ 10 */
  interestRate: number;
  /** 返済期間（年）※許容範囲: 1 ~ 50 */
  years: number;
  /** 【将来拡張用】ボーナス併用時の年間ボーナス返済額（円） */
  bonusAmount?: number;
  /** 【将来拡張用】ボーナス返済月（例: 6, 12月など） */
  bonusMonths?: number[];
}

/**
 * 年別の返済残高および内訳データ
 */
export interface YearlyBalance {
  /** 経過年数（年） */
  year: number;
  /** 年末時点の借入残高（円） */
  remainingBalance: number;
  /** 年間の元本返済合計（円） */
  totalPrincipal: number;
  /** 年間の利息支払い合計（円） */
  totalInterest: number;
}

import { useState, useMemo } from 'react';
import { LoanParams, YearlyBalance } from './types';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer
} from 'recharts';
import './index.css';

export default function App() {
  const [params, setParams] = useState<LoanParams>({
    amount: 30000000,
    interestRate: 1.5,
    years: 35
  });

  const handleChange = (field: keyof LoanParams, value: number) => {
    let validatedValue = value;
    if (field === 'amount') {
      validatedValue = Math.max(0, Math.min(1000000000, value));
    } else if (field === 'interestRate') {
      validatedValue = Math.max(0, Math.min(100, value));
    } else if (field === 'years') {
      validatedValue = Math.max(1, Math.min(100, value));
    }
    if (isNaN(validatedValue)) validatedValue = 0;
    setParams(prev => ({ ...prev, [field]: validatedValue }));
  };

  const { monthlyPayment, totalPayment, totalInterest, yearlyBalances } = useMemo(() => {
    const P = params.amount;
    const rMonth = params.interestRate / 100 / 12;
    const n = params.years * 12;

    let monthly = 0;
    if (n <= 0) {
      monthly = 0;
    } else if (rMonth === 0) {
      monthly = P / n;
    } else {
      monthly = (P * rMonth * Math.pow(1 + rMonth, n)) / (Math.pow(1 + rMonth, n) - 1);
    }
    if (isNaN(monthly) || !isFinite(monthly)) monthly = 0;

    let balance = P;
    let tInterest = 0;
    const balances: YearlyBalance[] = [];

    let currentYearPrincipal = 0;
    let currentYearInterest = 0;

    for (let month = 1; month <= n; month++) {
      const interest = balance * rMonth;
      const principal = monthly - interest;
      balance -= principal;
      if (balance < 0) balance = 0;

      tInterest += interest;
      currentYearPrincipal += principal;
      currentYearInterest += interest;

      if (month % 12 === 0 || month === n) {
        const yearNum = Math.ceil(month / 12);
        balances.push({
          year: yearNum,
          remainingBalance: Math.round(balance),
          totalPrincipal: Math.round(currentYearPrincipal),
          totalInterest: Math.round(currentYearInterest)
        });
        currentYearPrincipal = 0;
        currentYearInterest = 0;
      }
    }

    const tPayment = P + tInterest;

    return {
      monthlyPayment: Math.round(monthly),
      totalPayment: Math.round(tPayment),
      totalInterest: Math.round(tInterest),
      yearlyBalances: balances
    };
  }, [params]);

  return (
    <div className="app-container">
      <header className="header">
        <h1>住宅ローンシミュレーター</h1>
        <p>借入額・金利・返済期間を入力して、毎月の返済額や残高の推移を確認しましょう。</p>
      </header>

      <div className="simulator-grid">
        <div className="input-panel">
          <div className="input-group">
            <div className="label-row">
              <label htmlFor="amount-input">借入金額</label>
              <span>{(params.amount / 10000).toLocaleString()} 万円</span>
            </div>
            <input
              type="range"
              className="range-input"
              min={1000000}
              max={100000000}
              step={1000000}
              value={params.amount}
              onChange={e => handleChange('amount', Number(e.target.value))}
            />
            <input
              id="amount-input"
              type="number"
              className="input"
              min={0}
              max={1000000000}
              value={params.amount}
              step={100000}
              onChange={e => handleChange('amount', Number(e.target.value))}
            />
          </div>

          <div className="input-group">
            <div className="label-row">
              <label htmlFor="interest-rate-input">金利（年利）</label>
              <span>{params.interestRate.toFixed(2)} %</span>
            </div>
            <input
              type="range"
              className="range-input"
              min={0}
              max={10}
              step={0.1}
              value={params.interestRate}
              onChange={e => handleChange('interestRate', Number(e.target.value))}
            />
            <input
              id="interest-rate-input"
              type="number"
              className="input"
              min={0}
              max={100}
              value={params.interestRate}
              step={0.01}
              onChange={e => handleChange('interestRate', Number(e.target.value))}
            />
          </div>

          <div className="input-group">
            <div className="label-row">
              <label htmlFor="years-input">返済期間</label>
              <span>{params.years} 年</span>
            </div>
            <input
              type="range"
              className="range-input"
              min={1}
              max={50}
              step={1}
              value={params.years}
              onChange={e => handleChange('years', Number(e.target.value))}
            />
            <input
              id="years-input"
              type="number"
              className="input"
              min={1}
              max={100}
              value={params.years}
              step={1}
              onChange={e => handleChange('years', Number(e.target.value))}
            />
          </div>
        </div>

        <div className="result-panel">
          <div className="summary-cards">
            <div className="summary-card">
              <h3>毎月の返済額</h3>
              <div className="value">{monthlyPayment.toLocaleString()} 円</div>
            </div>
            <div className="summary-card">
              <h3>総支払額</h3>
              <div className="value">{totalPayment.toLocaleString()} 円</div>
            </div>
            <div className="summary-card">
              <h3>総利息額</h3>
              <div className="value">{totalInterest.toLocaleString()} 円</div>
            </div>
          </div>

          <div className="chart-card">
            <h2>残高の推移</h2>
            <div style={{ width: '100%', height: 300 }}>
              <ResponsiveContainer>
                <LineChart data={yearlyBalances}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="year" unit="年" />
                  <YAxis
                    tickFormatter={(val) => `${Math.round(val / 10000)}万円`}
                  />
                  <Tooltip
                    formatter={(val: number) => [`${val.toLocaleString()} 円`, '残高']}
                    labelFormatter={(label) => `${label}年目`}
                  />
                  <Legend />
                  <Line
                    type="monotone"
                    dataKey="remainingBalance"
                    name="借入残高"
                    stroke="#2563eb"
                    strokeWidth={2}
                    dot={false}
                  />
                </LineChart>
              </ResponsiveContainer>
            </div>
          </div>

          <div className="table-card">
            <h2>返済スケジュール（年別）</h2>
            <table className="table">
              <thead>
                <tr>
                  <th>経過年</th>
                  <th>残高</th>
                  <th>年間元本返済</th>
                  <th>年間利息</th>
                </tr>
              </thead>
              <tbody>
                {yearlyBalances.map((item) => (
                  <tr key={item.year}>
                    <td>{item.year}年目</td>
                    <td>{item.remainingBalance.toLocaleString()} 円</td>
                    <td>{item.totalPrincipal.toLocaleString()} 円</td>
                    <td>{item.totalInterest.toLocaleString()} 円</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
}
